$ErrorActionPreference = 'Stop'
Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public static class WCV {
    [StructLayout(LayoutKind.Sequential, CharSet=CharSet.Unicode)]
    public struct CREDENTIAL {
        public uint Flags; public uint Type; public IntPtr TargetName; public IntPtr Comment;
        public long LastWritten; public uint CredentialBlobSize; public IntPtr CredentialBlob;
        public uint Persist; public uint AttributeCount; public IntPtr Attributes;
        public IntPtr TargetAlias; public IntPtr UserName;
    }
    [DllImport("advapi32.dll", CharSet=CharSet.Unicode, SetLastError=true)]
    public static extern bool CredReadW(string target, uint type, uint flags, out IntPtr cred);
    [DllImport("advapi32.dll")]
    public static extern void CredFree(IntPtr cred);
}
'@
function Get-GitCred($gitHost) {
    foreach ($t in @("git:http://$gitHost", "git:http://tiany@$gitHost")) {
        $ptr = [IntPtr]::Zero
        if ([WCV]::CredReadW($t, 1, 0, [ref]$ptr)) {
            try {
                $c = [Runtime.InteropServices.Marshal]::PtrToStructure($ptr, [type][WCV+CREDENTIAL])
                $b = New-Object byte[] $c.CredentialBlobSize
                [Runtime.InteropServices.Marshal]::Copy($c.CredentialBlob, $b, 0, $c.CredentialBlobSize)
                return @{ user=[Runtime.InteropServices.Marshal]::PtrToStringUni($c.UserName); pass=[Text.Encoding]::Unicode.GetString($b) }
            } finally { [WCV]::CredFree($ptr) }
        }
    }
    return $null
}
$c = Get-GitCred 'gitlab.zhi.com'
if (-not $c) { Write-Output 'NO_CRED'; exit 3 }
$user = if ($c.user) { $c.user } else { 'tiany' }
$url = "http://$([uri]::EscapeDataString($user)):$([uri]::EscapeDataString($c.pass))@gitlab.zhi.com/zhishu/estate-manage.git"
$env:GIT_TERMINAL_PROMPT='0'
Push-Location 'D:\repository\苏住房后端'
try {
    Write-Output '===LSREMOTE==='
    & git -c credential.helper= ls-remote $url develop/v2.6.2-suzhufang-dev 2>&1
    Write-Output '===ORIGIN_URL==='
    & git remote get-url origin 2>&1
    Write-Output '===DIRTY_PATHS==='
    & git status --short --untracked-files=no 2>&1
} finally { Pop-Location }
